      if (allocated(state%s50)) deallocate (state%s50)
      if (allocated(state%n)) deallocate (state%n)
      state%npt = npt
      if (present(solver)) then
         allocate (state%solver, source=solver, stat=stat)
      else
         allocate (pcm_dense_solver :: state%solver, stat=stat)
      end if
      if (stat == 0) allocate (state%v(npt), stat=stat)
      if (stat == 0) allocate (state%r(3, npt), stat=stat)
      if (stat == 0) allocate (state%s4(npt), stat=stat)
      if (stat == 0) allocate (state%s5(npt), stat=stat)
      if (stat == 0) allocate (state%s6(npt), stat=stat)
      if (stat == 0) allocate (state%a(npt), stat=stat)
      if (stat == 0) allocate (state%s7(npt, npt), stat=stat)
      if (stat == 0) allocate (state%s8(npt), stat=stat)
      if (stat == 0) allocate (state%s9(npt), stat=stat)
      if (stat == 0) allocate (state%s10(npt), stat=stat)
      if (stat == 0) allocate (state%k1(npt), stat=stat)
      if (stat == 0) allocate (state%k2(npt), stat=stat)
      if (stat == 0) allocate (state%s11(npt, npt), stat=stat)
      if (stat == 0) allocate (state%s12(npt, npt), stat=stat)
      if (stat == 0) allocate (state%s13(npt, npt), stat=stat)
      if (stat == 0) allocate (state%s15(npt), stat=stat)
      if (stat == 0) allocate (state%s16(npt), stat=stat)
      if (stat == 0) allocate (state%s17(npt), stat=stat)
      if (stat == 0) allocate (state%s18(npt), stat=stat)
      if (stat == 0) allocate (state%s19(npt), stat=stat)
      if (stat == 0) allocate (state%s21(npt), stat=stat)
      if (stat == 0) allocate (state%s22(npt), stat=stat)
      if (stat == 0) allocate (state%s23(npt), stat=stat)
      if (stat == 0) allocate (state%s25(npt), stat=stat)
      if (stat == 0) allocate (state%s26(npt), stat=stat)
      if (stat == 0) allocate (state%s28(npt), stat=stat)
      if (stat == 0) allocate (state%s29(npt), stat=stat)
      if (stat == 0) allocate (state%s30(npt), stat=stat)
      if (stat == 0) allocate (state%s31(npt), stat=stat)
      if (stat == 0) allocate (state%s32(npt), stat=stat)
      if (stat == 0) allocate (state%s33(npt), stat=stat)
      if (stat == 0) allocate (state%s34(npt), stat=stat)
      if (stat == 0) allocate (state%s36(npt), stat=stat)
      if (stat == 0) allocate (state%s37(npt), stat=stat)
      if (stat == 0) allocate (state%s38(npt), stat=stat)
      if (stat == 0) allocate (state%s40(npt), stat=stat)
      if (stat == 0) allocate (state%s41(npt), stat=stat)
      if (stat == 0) allocate (state%s42(npt), stat=stat)
      if (stat == 0) allocate (state%s43(npt), stat=stat)
      if (stat == 0) allocate (state%s44(npt), stat=stat)
      if (stat == 0) allocate (state%s45(npt), stat=stat)
      if (stat == 0) allocate (state%s46(npt), stat=stat)
      if (stat == 0) allocate (state%s47(npt), stat=stat)
      if (stat == 0) allocate (state%s48(npt), stat=stat)
      if (stat == 0) allocate (state%s49(npt), stat=stat)
      if (stat == 0) allocate (state%s50(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[lpb_point_assemble] allocation failed")
         return
      end if
      state%s17 = 0.0_wp
      state%s19 = 0.0_wp
      state%s21 = 0.0_wp
      state%s23 = 0.0_wp
      call state%solver%reset(lpb_point_n_operators)
      state%matrix_free = .false.

      state%r = r
      state%a = a
      state%k1 = k1
      state%k2 = k2
      state%op1%npt = npt
      state%op1%npoint = npt
      state%op1%id = 1
      state%op1%points => state%r
      state%op1%symmetric = .true.
      !$omp parallel do default(none) schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(npt, state)
      do j = 1, npt
         block
            real(wp) :: tmp1, tmp2, tmp3, tmp4, tmp5, tmp6, tmp7, tmp8, tmp9, tmp10, tmp11, tmp12

            do i = 1, j - 1
               tmp1 = -state%r(1, j)
               tmp2 = state%r(1, i) + tmp1
               tmp3 = tmp2**(2)
               tmp4 = -state%r(2, j)
               tmp5 = state%r(2, i) + tmp4
               tmp6 = tmp5**(2)
               tmp7 = tmp3 + tmp6
               tmp8 = -state%r(3, j)
               tmp9 = state%r(3, i) + tmp8
               tmp10 = tmp9**(2)
               tmp11 = tmp7 + tmp10
               tmp12 = 1.0_wp/sqrt(tmp11)
               state%s7(i, j) = tmp12
               state%s7(j, i) = tmp12
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, npt
         tmp13 = 1.0_wp/state%a(i)
         tmp14 = 12.566370614359172_wp*tmp13
         tmp15 = sqrt(tmp14)
         tmp16 = 1.0694_wp*tmp15
         state%s7(i, i) = tmp16
      end do
      state%op1%c1 => state%s7
      call state%solver%setup(state%op1, error)
      if (allocated(error)) return
      state%s4 = state%r(1, :)
      state%s5 = state%r(2, :)
      state%s6 = state%r(3, :)
      state%s8 = n(1, :)
      state%s9 = n(2, :)
      state%s10 = n(3, :)
      !$omp parallel do default(none) schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(npt, state)
      do j = 1, npt
         block
            real(wp) :: tmp17, tmp18, tmp19, tmp20, tmp21, tmp22, tmp23, tmp24, tmp25, tmp26, &
                        tmp27, tmp28, tmp29, tmp30, tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, &
                        tmp37, tmp38, tmp39, tmp40, tmp41, tmp42, tmp43, tmp44

            do i = 1, j - 1
               tmp17 = -state%s4(j)
               tmp18 = state%s4(i) + tmp17
               tmp19 = state%s8(j)*tmp18
               tmp20 = -state%s5(j)
               tmp21 = state%s5(i) + tmp20
               tmp22 = tmp21*state%s9(j)
               tmp23 = tmp19 + tmp22
               tmp24 = -state%s6(j)
               tmp25 = state%s6(i) + tmp24
               tmp26 = tmp25*state%s10(j)
               tmp27 = tmp23 + tmp26
               tmp28 = tmp18**(2)
               tmp29 = tmp21**(2)
               tmp30 = tmp28 + tmp29
               tmp31 = tmp25**(2)
               tmp32 = tmp30 + tmp31
               tmp33 = 1.0_wp/sqrt(tmp32)
               tmp34 = tmp33**(3)
               tmp35 = tmp27*tmp34
               state%s13(i, j) = tmp35
               tmp36 = -tmp18
               tmp37 = state%s8(i)*tmp36
               tmp38 = -tmp21
               tmp39 = tmp38*state%s9(i)
               tmp40 = tmp37 + tmp39
               tmp41 = -tmp25
               tmp42 = tmp41*state%s10(i)
               tmp43 = tmp40 + tmp42
               tmp44 = tmp43*tmp34
               state%s13(j, i) = tmp44
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, npt
         tmp45 = state%k1(i) + state%k2(i)
         tmp46 = 1.0_wp/state%a(i)
         tmp47 = 12.566370614359172_wp*tmp46
         tmp48 = sqrt(tmp47)
         tmp49 = tmp45*tmp48
         tmp50 = (-0.26735_wp)*tmp49
         state%s13(i, i) = tmp50
      end do

      state%ready = 1
      state%assembled = state%assembled + 1
   end subroutine lpb_point_assemble

   !> Linearized Poisson-Boltzmann (point charges): combine and factor the operators for the solvent
   !>
   !> - Repeat with new solvent inputs as often as needed; the cavity operators are reused
   !> - Needs lpb_point_assemble on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of lpb_point
   !> @param[in] eps  relative permittivity of the solvent (inf for a conductor)
   !> @param[in] kappa  inverse Debye screening length of the ionic solvent
   !> @param[out] error  error handling; allocated on failure
   subroutine lpb_point_medium(state, eps, kappa, error)
      !> State of lpb_point
      type(lpb_point_state), target, intent(inout) :: state
      !> Relative permittivity of the solvent (inf for a conductor)
      real(wp), intent(in) :: eps
      !> Inverse Debye screening length of the ionic solvent
      real(wp), intent(in) :: kappa
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp) :: tmp1, tmp39, tmp40, tmp41, tmp42, tmp43, tmp44, tmp62, tmp63, tmp64, tmp65, &
                  tmp66, tmp67
      integer :: i, j

      if (state%matrix_free) then
         call lpb_point_mf_medium(state, eps, kappa, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, "[lpb_point_medium] call lpb_point_assemble first")
         return
      end if
      state%ready = 1
      ! Inputs that do not enter these outputs
      associate (unused1 => eps)
      end associate

      state%op1%points => state%r
      state%op1%c1 => state%s7
      state%kappa = kappa
      state%op2%npt = npt
      state%op2%npoint = npt
      state%op2%id = 2
      state%op2%points => state%r
      state%op2%a => state%a
      state%s1 = eps + 1.0_wp
      state%s2 = 1.0_wp/state%s1
      tmp1 = -state%s2
      state%s3 = 1.0_wp + tmp1
      state%op2%c1 = state%s3
      state%op2%c2 => state%s7
      !$omp parallel do default(none) schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(npt, state)
      do j = 1, npt
         block
            real(wp) :: tmp2, tmp3, tmp4, tmp5, tmp6, tmp7, tmp8, tmp9, tmp10, tmp11, tmp12, &
                        tmp13, tmp14, tmp15, tmp16, tmp17, tmp18, tmp19, tmp20, tmp21, tmp22, &
                        tmp23, tmp24, tmp25, tmp26, tmp27, tmp28, tmp29, tmp30, tmp31, tmp32, &
                        tmp33, tmp34, tmp35, tmp36, tmp37, tmp38

            do i = 1, j - 1
               tmp2 = -state%s4(j)
               tmp3 = state%s4(i) + tmp2
               tmp4 = state%s8(j)*tmp3
               tmp5 = -state%s5(j)
               tmp6 = state%s5(i) + tmp5
               tmp7 = tmp6*state%s9(j)
               tmp8 = tmp4 + tmp7
               tmp9 = -state%s6(j)
               tmp10 = state%s6(i) + tmp9
               tmp11 = tmp10*state%s10(j)
               tmp12 = tmp8 + tmp11
               tmp13 = tmp3**(2)
               tmp14 = tmp6**(2)
               tmp15 = tmp13 + tmp14
               tmp16 = tmp10**(2)
               tmp17 = tmp15 + tmp16
               tmp18 = 1.0_wp/sqrt(tmp17)
               tmp19 = tmp18**(3)
               tmp20 = tmp12*tmp19
               tmp21 = sqrt(tmp17)
               tmp22 = tmp21*state%kappa
               tmp23 = -tmp22
               tmp24 = exp(tmp23)
               tmp25 = tmp20*tmp24
               tmp26 = 1.0_wp + tmp22
               tmp27 = tmp25*tmp26
               state%s11(i, j) = tmp27
               tmp28 = -tmp3
               tmp29 = state%s8(i)*tmp28
               tmp30 = -tmp6
               tmp31 = tmp30*state%s9(i)
               tmp32 = tmp29 + tmp31
               tmp33 = -tmp10
               tmp34 = tmp33*state%s10(i)
               tmp35 = tmp32 + tmp34
               tmp36 = tmp35*tmp19
               tmp37 = tmp36*tmp24
               tmp38 = tmp37*tmp26
               state%s11(j, i) = tmp38
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, npt
         tmp39 = state%k1(i) + state%k2(i)
         tmp40 = 1.0_wp/state%a(i)
         tmp41 = 12.566370614359172_wp*tmp40
         tmp42 = sqrt(tmp41)
         tmp43 = tmp39*tmp42
         tmp44 = (-0.26735_wp)*tmp43
         state%s11(i, i) = tmp44
      end do
      state%op2%c3 => state%s11
      state%op2%c4 = state%s2
      !$omp parallel do default(none) schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(npt, state)
      do j = 1, npt
         block
            real(wp) :: tmp45, tmp46, tmp47, tmp48, tmp49, tmp50, tmp51, tmp52, tmp53, tmp54, &
                        tmp55, tmp56, tmp57, tmp58, tmp59, tmp60, tmp61

            do i = 1, j - 1
               tmp45 = -state%s4(j)
               tmp46 = state%s4(i) + tmp45
               tmp47 = tmp46**(2)
               tmp48 = -state%s5(j)
               tmp49 = state%s5(i) + tmp48
               tmp50 = tmp49**(2)
               tmp51 = tmp47 + tmp50
               tmp52 = -state%s6(j)
               tmp53 = state%s6(i) + tmp52
               tmp54 = tmp53**(2)
               tmp55 = tmp51 + tmp54
               tmp56 = 1.0_wp/sqrt(tmp55)
               tmp57 = sqrt(tmp55)
               tmp58 = tmp57*state%kappa
               tmp59 = -tmp58
               tmp60 = exp(tmp59)
               tmp61 = tmp56*tmp60
               state%s12(i, j) = tmp61
               state%s12(j, i) = tmp61
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, npt
         tmp62 = 1.0_wp/state%a(i)
         tmp63 = 12.566370614359172_wp*tmp62
         tmp64 = sqrt(tmp63)
         tmp65 = 1.0694_wp*tmp64
         tmp66 = -state%kappa
         tmp67 = tmp65 + tmp66
         state%s12(i, i) = tmp67
      end do
      state%op2%c5 => state%s12
      state%op2%c6 => state%s13
      call state%solver%setup(state%op2, error)
      if (allocated(error)) return
      state%s14 = -state%s3
      state%s20 = 0.5_wp*state%s2
      state%s24 = (-0.5_wp)*state%s3
      state%s27 = 0.07957747154594767_wp*state%s3

      state%ready = 2
   end subroutine lpb_point_medium

   !> Linearized Poisson-Boltzmann (point charges): energy, solution and gradient for v
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs lpb_point_medium on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of lpb_point
   !> @param[in] v  solute electrostatic potential at the surface points
   !> @param[out] energy  solvation energy
   !> @param[out] q  apparent surface charges
   !> @param[out] grad_v  partial derivative of the energy with respect to v
   !> @param[out] error  error handling; allocated on failure
   subroutine lpb_point_solve(state, v, energy, q, grad_v, error)
      !> State of lpb_point
      type(lpb_point_state), target, intent(inout) :: state
      !> Solute electrostatic potential at the surface points
      real(wp), contiguous, intent(in) :: v(:)
      !> Solvation energy
      real(wp), intent(out) :: energy
      !> Apparent surface charges
      real(wp), contiguous, intent(out) :: q(:)
      !> Partial derivative of the energy with respect to v
      real(wp), contiguous, intent(out) :: grad_v(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:), tmp5(:), tmp6(:), tmp7(:), &
                               tmp8(:), tmp9(:), tmp10(:), tmp12(:), tmp13(:), tmp14(:), tmp15(:), &
                               tmp16(:), tmp17(:), tmp18(:), tmp19(:), tmp20(:), tmp21(:), &
                               tmp22(:), tmp23(:), tmp24(:), tmp25(:), tmp26(:), tmp27(:), &
                               tmp28(:), tmp29(:), tmp30(:), tmp31(:), tmp33(:), tmp34(:), &
                               tmp35(:)
      real(wp) :: tmp11, tmp32, tmp36, tmp37

      if (state%matrix_free) then
         call lpb_point_mf_solve(state, v, energy, q, grad_v, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 2) then
         call fatal_error(error, "[lpb_point_solve] call lpb_point_medium first")
         return
      end if
      if (any(shape(v) /= [npt])) then
         call fatal_error(error, "[lpb_point_solve] v: wrong shape")
         return
      end if
      if (any(shape(q) /= [npt])) then
         call fatal_error(error, "[lpb_point_solve] q: wrong shape")
         return
      end if
      if (any(shape(grad_v) /= [npt])) then
         call fatal_error(error, "[lpb_point_solve] grad_v: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp8(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat == 0) allocate (tmp12(npt), stat=stat)
      if (stat == 0) allocate (tmp13(npt), stat=stat)
      if (stat == 0) allocate (tmp14(npt), stat=stat)
      if (stat == 0) allocate (tmp15(npt), stat=stat)
      if (stat == 0) allocate (tmp16(npt), stat=stat)
      if (stat == 0) allocate (tmp17(npt), stat=stat)
      if (stat == 0) allocate (tmp18(npt), stat=stat)
      if (stat == 0) allocate (tmp19(npt), stat=stat)
      if (stat == 0) allocate (tmp20(npt), stat=stat)
      if (stat == 0) allocate (tmp21(npt), stat=stat)
      if (stat == 0) allocate (tmp22(npt), stat=stat)
      if (stat == 0) allocate (tmp23(npt), stat=stat)
      if (stat == 0) allocate (tmp24(npt), stat=stat)
      if (stat == 0) allocate (tmp25(npt), stat=stat)
      if (stat == 0) allocate (tmp26(npt), stat=stat)
      if (stat == 0) allocate (tmp27(npt), stat=stat)
      if (stat == 0) allocate (tmp28(npt), stat=stat)
      if (stat == 0) allocate (tmp29(npt), stat=stat)
      if (stat == 0) allocate (tmp30(npt), stat=stat)
      if (stat == 0) allocate (tmp31(npt), stat=stat)
      if (stat == 0) allocate (tmp33(npt), stat=stat)
      if (stat == 0) allocate (tmp34(npt), stat=stat)
      if (stat == 0) allocate (tmp35(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[lpb_point_solve] allocation failed")
         return
      end if
      state%ready = 2

      state%op1%points => state%r
      state%op1%c1 => state%s7
      state%op2%points => state%r
      state%op2%a => state%a
      state%op2%c2 => state%s7
      state%op2%c3 => state%s11
      state%op2%c5 => state%s12
      state%op2%c6 => state%s13
      state%v = v
      state%s15 = state%a*state%v
      call gemv(state%s11, state%s15, tmp1)
      tmp2 = (-0.15915494309189535_wp)*tmp1
      state%s16 = state%v + tmp2
      call gemv(state%s13, state%s15, tmp3)
      tmp4 = (-0.15915494309189535_wp)*tmp3
      tmp5 = state%v + tmp4
      call state%solver%solve(state%op1, .false., tmp5, state%s17, error)
      if (allocated(error)) return
      call gemv(state%s12, state%s17, state%s18)
      tmp6 = state%s14*state%s16
      tmp7 = state%s2*state%s18
      tmp8 = tmp6 + tmp7
      call state%solver%solve(state%op2, .false., tmp8, state%s19, error)
      if (allocated(error)) return
      call state%solver%solve(state%op2, .true., state%v, state%s21, error)
      if (allocated(error)) return
      state%s22 = state%s20*state%s21
      call gemv(state%s12, state%s22, tmp9, trans="t")
      call state%solver%solve(state%op1, .false., tmp9, state%s23, error)
      if (allocated(error)) return
      state%s25 = state%s24*state%s21
      state%s26 = (-0.15915494309189535_wp)*state%s23
      state%s28 = state%s27*state%s21
      call gemv(state%s11, state%s28, state%s29, trans="t")
      call gemv(state%s13, state%s26, tmp10, trans="t")
      state%s30 = tmp10 + state%s29
      tmp11 = dot(state%v, state%s19)
      energy = 0.5_wp*tmp11
      q = state%s19
      tmp12 = 0.5_wp*state%s19
      tmp13 = tmp12 + state%s23
      tmp14 = tmp13 + state%s25
      tmp15 = state%s30*state%a
      grad_v = tmp14 + tmp15
      if (state%solver%inexact()) then
         ! First-order correction for the residuals of the solves
         tmp16 = 0.5_wp*state%s21
         call gemv(state%s7, state%s19, tmp17)
         tmp18 = state%a*tmp17
         call gemv(state%s11, tmp18, tmp19)
         tmp20 = (-0.15915494309189535_wp)*tmp19
         tmp21 = tmp17 + tmp20
         tmp22 = state%s3*tmp21
         call gemv(state%s13, state%s19, tmp23, trans="t")
         tmp24 = state%a*tmp23
         tmp25 = 0.15915494309189535_wp*tmp24
         tmp26 = state%s19 + tmp25
         call gemv(state%s12, tmp26, tmp27)
         tmp28 = state%s2*tmp27
         tmp29 = tmp22 + tmp28
         tmp30 = -tmp29
         tmp31 = tmp8 + tmp30
         tmp32 = dot(tmp16, tmp31)
         call gemv(state%s7, state%s17, tmp33)
         tmp34 = -tmp33
         tmp35 = tmp5 + tmp34
         tmp36 = dot(state%s23, tmp35)
         tmp37 = tmp32 + tmp36
         energy = energy + tmp37
      end if

      state%ready = 3
   end subroutine lpb_point_solve

   !> Linearized Poisson-Boltzmann (point charges): energy gradient with respect to the other inputs
   !>
   !> - For the inputs of the last solve
   !> - Needs lpb_point_solve on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of lpb_point
   !> @param[out] grad_r  partial derivative of the energy with respect to r
   !> @param[out] grad_n  partial derivative of the energy with respect to n
   !> @param[out] grad_k1  partial derivative of the energy with respect to k1
   !> @param[out] grad_k2  partial derivative of the energy with respect to k2
   !> @param[out] grad_a  partial derivative of the energy with respect to a
   !> @param[out] grad_eps  partial derivative of the energy with respect to eps
   !> @param[out] grad_kappa  partial derivative of the energy with respect to kappa
   !> @param[out] error  error handling; allocated on failure
   subroutine lpb_point_weights(state, grad_r, grad_n, grad_k1, grad_k2, grad_a, grad_eps, &
                                grad_kappa, error)
      !> State of lpb_point
      type(lpb_point_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to r
      real(wp), contiguous, intent(out) :: grad_r(:, :)
      !> Partial derivative of the energy with respect to n
      real(wp), contiguous, intent(out) :: grad_n(:, :)
      !> Partial derivative of the energy with respect to k1
      real(wp), contiguous, intent(out) :: grad_k1(:)
      !> Partial derivative of the energy with respect to k2
      real(wp), contiguous, intent(out) :: grad_k2(:)
