      if (allocated(state%cx_s43)) deallocate (state%cx_s43)
      if (allocated(state%cx_s44)) deallocate (state%cx_s44)
      if (allocated(state%cx_s45)) deallocate (state%cx_s45)
      if (allocated(state%cx_s46)) deallocate (state%cx_s46)
      if (allocated(state%cx_s47)) deallocate (state%cx_s47)
      if (allocated(state%cx_s48)) deallocate (state%cx_s48)
      if (allocated(state%cx_s49)) deallocate (state%cx_s49)
      if (allocated(state%cx_s50)) deallocate (state%cx_s50)
      if (stat == 0) allocate (state%cx_v(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s11(npt, npt), stat=stat)
      if (stat == 0) allocate (state%cx_s12(npt, npt), stat=stat)
