      if (stat == 0) allocate (state%cx_s17(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s18(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s19(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s21(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s22(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s23(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s25(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s26(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s28(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s29(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s30(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s31(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s32(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s33(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s34(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s36(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s37(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s38(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s40(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s41(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s42(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s43(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s44(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s45(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s46(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s47(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s48(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s49(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s50(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[lpb_point_complex_medium] allocation failed")
         return
      end if
      state%cx_s17 = 0.0_wp
      state%cx_s19 = 0.0_wp
      state%cx_s21 = 0.0_wp
      state%cx_s23 = 0.0_wp
      state%cx_ready = 1
      state%cx_assembled = state%assembled
      ! Inputs that do not enter these outputs
      associate (unused1 => eps)
      end associate

      state%op1%points => state%r
      state%op1%c1 => state%s7
      state%cx_kappa = kappa
      state%op5%npt = npt
      state%op5%npoint = npt
      state%op5%id = 5
      state%op5%points => state%r
      state%op5%a => state%a
      state%cx_s1 = eps + 1.0_wp
      state%cx_s2 = 1.0_wp/state%cx_s1
      tmp1 = -state%cx_s2
      state%cx_s3 = 1.0_wp + tmp1
      state%op5%c1 = state%cx_s3
      state%op5%c2 => state%s7
      !$omp parallel do default(none) schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(npt, state)
      do j = 1, npt
         block
            real(wp) :: tmp2, tmp3, tmp4, tmp5, tmp6, tmp7, tmp8, tmp9, tmp10, tmp11, tmp12, &
                        tmp13, tmp14, tmp15, tmp16, tmp17, tmp18, tmp19, tmp20, tmp21, tmp22, &
                        tmp23, tmp24, tmp25, tmp26, tmp27, tmp28, tmp29, tmp30, tmp31, tmp32, &
                        tmp33, tmp34, tmp35, tmp36, tmp37, tmp38

            do i = 1, j - 1
               tmp2 = -state%s4(j)
               tmp3 = state%s4(i) + tmp2
               tmp4 = state%s8(j)*tmp3
               tmp5 = -state%s5(j)
               tmp6 = state%s5(i) + tmp5
               tmp7 = tmp6*state%s9(j)
               tmp8 = tmp4 + tmp7
               tmp9 = -state%s6(j)
               tmp10 = state%s6(i) + tmp9
               tmp11 = tmp10*state%s10(j)
               tmp12 = tmp8 + tmp11
               tmp13 = tmp3**(2)
               tmp14 = tmp6**(2)
               tmp15 = tmp13 + tmp14
               tmp16 = tmp10**(2)
               tmp17 = tmp15 + tmp16
               tmp18 = 1.0_wp/sqrt(tmp17)
               tmp19 = tmp18**(3)
               tmp20 = tmp12*tmp19
               tmp21 = sqrt(tmp17)
               tmp22 = tmp21*state%cx_kappa
               tmp23 = -tmp22
               tmp24 = exp(tmp23)
               tmp25 = tmp20*tmp24
               tmp26 = 1.0_wp + tmp22
               tmp27 = tmp25*tmp26
               state%cx_s11(i, j) = tmp27
               tmp28 = -tmp3
               tmp29 = state%s8(i)*tmp28
               tmp30 = -tmp6
               tmp31 = tmp30*state%s9(i)
               tmp32 = tmp29 + tmp31
               tmp33 = -tmp10
               tmp34 = tmp33*state%s10(i)
               tmp35 = tmp32 + tmp34
               tmp36 = tmp35*tmp19
               tmp37 = tmp36*tmp24
               tmp38 = tmp37*tmp26
               state%cx_s11(j, i) = tmp38
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, npt
         tmp39 = state%k1(i) + state%k2(i)
         tmp40 = 1.0_wp/state%a(i)
         tmp41 = 12.566370614359172_wp*tmp40
         tmp42 = sqrt(tmp41)
         tmp43 = tmp39*tmp42
         tmp44 = (-0.26735_wp)*tmp43
         state%cx_s11(i, i) = tmp44
      end do
      state%op5%c3 => state%cx_s11
      state%op5%c4 = state%cx_s2
      !$omp parallel do default(none) schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(npt, state)
      do j = 1, npt
         block
            real(wp) :: tmp45, tmp46, tmp47, tmp48, tmp49, tmp50, tmp51, tmp52, tmp53, tmp54, &
                        tmp55, tmp56, tmp57, tmp58, tmp59, tmp60, tmp61

            do i = 1, j - 1
               tmp45 = -state%s4(j)
               tmp46 = state%s4(i) + tmp45
               tmp47 = tmp46**(2)
               tmp48 = -state%s5(j)
               tmp49 = state%s5(i) + tmp48
               tmp50 = tmp49**(2)
               tmp51 = tmp47 + tmp50
               tmp52 = -state%s6(j)
               tmp53 = state%s6(i) + tmp52
               tmp54 = tmp53**(2)
               tmp55 = tmp51 + tmp54
               tmp56 = 1.0_wp/sqrt(tmp55)
               tmp57 = sqrt(tmp55)
               tmp58 = tmp57*state%cx_kappa
               tmp59 = -tmp58
               tmp60 = exp(tmp59)
               tmp61 = tmp56*tmp60
               state%cx_s12(i, j) = tmp61
               state%cx_s12(j, i) = tmp61
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, npt
         tmp62 = 1.0_wp/state%a(i)
         tmp63 = 12.566370614359172_wp*tmp62
         tmp64 = sqrt(tmp63)
         tmp65 = 1.0694_wp*tmp64
         tmp66 = -state%cx_kappa
         tmp67 = tmp65 + tmp66
         state%cx_s12(i, i) = tmp67
      end do
      state%op5%c5 => state%cx_s12
      state%op5%c6 => state%s13
      call state%solver%setup_complex(state%op5, error)
      if (allocated(error)) return
      state%cx_s14 = -state%cx_s3
      state%cx_s20 = 0.5_wp*state%cx_s2
      state%cx_s24 = (-0.5_wp)*state%cx_s3
      state%cx_s27 = 0.07957747154594767_wp*state%cx_s3

      state%cx_ready = 2
   end subroutine lpb_point_complex_medium

   !> Linearized Poisson-Boltzmann (point charges): energy, solution and gradient for v
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs lpb_point_complex_medium on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of lpb_point
   !> @param[in] v  solute electrostatic potential at the surface points
   !> @param[out] energy  solvation energy
   !> @param[out] q  apparent surface charges
   !> @param[out] grad_v  partial derivative of the energy with respect to v
   !> @param[out] error  error handling; allocated on failure
   subroutine lpb_point_complex_solve(state, v, energy, q, grad_v, error)
      !> State of lpb_point
      type(lpb_point_complex_state), target, intent(inout) :: state
      !> Solute electrostatic potential at the surface points
      complex(wp), contiguous, intent(in) :: v(:)
      !> Solvation energy
      complex(wp), intent(out) :: energy
      !> Apparent surface charges
      complex(wp), contiguous, intent(out) :: q(:)
      !> Partial derivative of the energy with respect to v
      complex(wp), contiguous, intent(out) :: grad_v(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp2(:), tmp3(:), tmp6(:), tmp7(:), tmp10(:), tmp11(:), tmp16(:), &
                               tmp17(:), tmp18(:), tmp19(:), tmp21(:), tmp22(:), tmp30(:), &
                               tmp31(:), tmp34(:), tmp35(:), tmp40(:), tmp41(:), tmp46(:), &
                               tmp47(:), tmp54(:), tmp55(:)
      complex(wp), allocatable :: tmp1(:), tmp4(:), tmp5(:), tmp8(:), tmp9(:), tmp12(:), tmp13(:), &
                                  tmp14(:), tmp15(:), tmp20(:), tmp24(:), tmp25(:), tmp26(:), &
                                  tmp27(:), tmp28(:), tmp29(:), tmp32(:), tmp33(:), tmp36(:), &
                                  tmp37(:), tmp38(:), tmp39(:), tmp42(:), tmp43(:), tmp44(:), &
                                  tmp45(:), tmp48(:), tmp49(:), tmp50(:), tmp51(:), tmp53(:), &
                                  tmp56(:), tmp57(:)
      complex(wp) :: tmp23, tmp52, tmp58, tmp59

      if (state%matrix_free) then
         call lpb_point_complex_mf_solve(state, v, energy, q, grad_v, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%cx_ready < 2 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, "[lpb_point_complex_solve] call lpb_point_complex_medium first")
         return
      end if
      if (any(shape(v) /= [npt])) then
         call fatal_error(error, "[lpb_point_complex_solve] v: wrong shape")
         return
      end if
      if (any(shape(q) /= [npt])) then
         call fatal_error(error, "[lpb_point_complex_solve] q: wrong shape")
         return
      end if
      if (any(shape(grad_v) /= [npt])) then
         call fatal_error(error, "[lpb_point_complex_solve] grad_v: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp8(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat == 0) allocate (tmp11(npt), stat=stat)
      if (stat == 0) allocate (tmp12(npt), stat=stat)
      if (stat == 0) allocate (tmp13(npt), stat=stat)
      if (stat == 0) allocate (tmp14(npt), stat=stat)
      if (stat == 0) allocate (tmp15(npt), stat=stat)
      if (stat == 0) allocate (tmp16(npt), stat=stat)
      if (stat == 0) allocate (tmp17(npt), stat=stat)
      if (stat == 0) allocate (tmp18(npt), stat=stat)
      if (stat == 0) allocate (tmp19(npt), stat=stat)
      if (stat == 0) allocate (tmp20(npt), stat=stat)
      if (stat == 0) allocate (tmp21(npt), stat=stat)
      if (stat == 0) allocate (tmp22(npt), stat=stat)
      if (stat == 0) allocate (tmp24(npt), stat=stat)
      if (stat == 0) allocate (tmp25(npt), stat=stat)
      if (stat == 0) allocate (tmp26(npt), stat=stat)
      if (stat == 0) allocate (tmp27(npt), stat=stat)
      if (stat == 0) allocate (tmp28(npt), stat=stat)
      if (stat == 0) allocate (tmp29(npt), stat=stat)
      if (stat == 0) allocate (tmp30(npt), stat=stat)
      if (stat == 0) allocate (tmp31(npt), stat=stat)
      if (stat == 0) allocate (tmp32(npt), stat=stat)
      if (stat == 0) allocate (tmp33(npt), stat=stat)
      if (stat == 0) allocate (tmp34(npt), stat=stat)
      if (stat == 0) allocate (tmp35(npt), stat=stat)
      if (stat == 0) allocate (tmp36(npt), stat=stat)
      if (stat == 0) allocate (tmp37(npt), stat=stat)
      if (stat == 0) allocate (tmp38(npt), stat=stat)
      if (stat == 0) allocate (tmp39(npt), stat=stat)
      if (stat == 0) allocate (tmp40(npt), stat=stat)
      if (stat == 0) allocate (tmp41(npt), stat=stat)
      if (stat == 0) allocate (tmp42(npt), stat=stat)
      if (stat == 0) allocate (tmp43(npt), stat=stat)
      if (stat == 0) allocate (tmp44(npt), stat=stat)
      if (stat == 0) allocate (tmp45(npt), stat=stat)
      if (stat == 0) allocate (tmp46(npt), stat=stat)
      if (stat == 0) allocate (tmp47(npt), stat=stat)
      if (stat == 0) allocate (tmp48(npt), stat=stat)
      if (stat == 0) allocate (tmp49(npt), stat=stat)
      if (stat == 0) allocate (tmp50(npt), stat=stat)
      if (stat == 0) allocate (tmp51(npt), stat=stat)
      if (stat == 0) allocate (tmp53(npt), stat=stat)
      if (stat == 0) allocate (tmp54(npt), stat=stat)
      if (stat == 0) allocate (tmp55(npt), stat=stat)
      if (stat == 0) allocate (tmp56(npt), stat=stat)
      if (stat == 0) allocate (tmp57(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[lpb_point_complex_solve] allocation failed")
         return
      end if
      state%cx_ready = 2

      state%op1%points => state%r
      state%op1%c1 => state%s7
      state%op5%points => state%r
      state%op5%a => state%a
      state%op5%c2 => state%s7
      state%op5%c3 => state%cx_s11
      state%op5%c5 => state%cx_s12
      state%op5%c6 => state%s13
      state%cx_v = v
      state%cx_s15 = state%a*state%cx_v
      call gemv(state%cx_s11, real(state%cx_s15, wp), tmp2)
      call gemv(state%cx_s11, aimag(state%cx_s15), tmp3)
      tmp1 = cmplx(tmp2, tmp3, wp)
      tmp4 = (-0.15915494309189535_wp)*tmp1
      state%cx_s16 = state%cx_v + tmp4
      call gemv(state%s13, real(state%cx_s15, wp), tmp6)
      call gemv(state%s13, aimag(state%cx_s15), tmp7)
      tmp5 = cmplx(tmp6, tmp7, wp)
      tmp8 = (-0.15915494309189535_wp)*tmp5
      tmp9 = state%cx_v + tmp8
      call state%solver%solve_complex(state%op1, .false., tmp9, state%cx_s17, error)
      if (allocated(error)) return
      call gemv(state%cx_s12, real(state%cx_s17, wp), tmp10)
      call gemv(state%cx_s12, aimag(state%cx_s17), tmp11)
      state%cx_s18 = cmplx(tmp10, tmp11, wp)
      tmp12 = state%cx_s14*state%cx_s16
      tmp13 = state%cx_s2*state%cx_s18
      tmp14 = tmp12 + tmp13
      call state%solver%solve_complex(state%op5, .false., tmp14, state%cx_s19, error)
      if (allocated(error)) return
      call state%solver%solve_complex(state%op5, .true., state%cx_v, state%cx_s21, error)
      if (allocated(error)) return
      state%cx_s22 = state%cx_s20*state%cx_s21
      call gemv(state%cx_s12, real(state%cx_s22, wp), tmp16, trans="t")
      call gemv(state%cx_s12, aimag(state%cx_s22), tmp17, trans="t")
      tmp15 = cmplx(tmp16, tmp17, wp)
      call state%solver%solve_complex(state%op1, .false., tmp15, state%cx_s23, error)
      if (allocated(error)) return
      state%cx_s25 = state%cx_s24*state%cx_s21
      state%cx_s26 = (-0.15915494309189535_wp)*state%cx_s23
      state%cx_s28 = state%cx_s27*state%cx_s21
      call gemv(state%cx_s11, real(state%cx_s28, wp), tmp18, trans="t")
      call gemv(state%cx_s11, aimag(state%cx_s28), tmp19, trans="t")
      state%cx_s29 = cmplx(tmp18, tmp19, wp)
      call gemv(state%s13, real(state%cx_s26, wp), tmp21, trans="t")
      call gemv(state%s13, aimag(state%cx_s26), tmp22, trans="t")
      tmp20 = cmplx(tmp21, tmp22, wp)
      state%cx_s30 = tmp20 + state%cx_s29
      tmp23 = sum(state%cx_v*state%cx_s19)
      energy = 0.5_wp*tmp23
      q = state%cx_s19
      tmp24 = 0.5_wp*state%cx_s19
      tmp25 = tmp24 + state%cx_s23
      tmp26 = tmp25 + state%cx_s25
      tmp27 = state%cx_s30*state%a
      grad_v = tmp26 + tmp27
      if (state%solver%inexact()) then
         ! First-order correction for the residuals of the solves
         tmp28 = 0.5_wp*state%cx_s21
         call gemv(state%s7, real(state%cx_s19, wp), tmp30)
         call gemv(state%s7, aimag(state%cx_s19), tmp31)
         tmp29 = cmplx(tmp30, tmp31, wp)
         tmp32 = state%a*tmp29
         call gemv(state%cx_s11, real(tmp32, wp), tmp34)
         call gemv(state%cx_s11, aimag(tmp32), tmp35)
         tmp33 = cmplx(tmp34, tmp35, wp)
         tmp36 = (-0.15915494309189535_wp)*tmp33
         tmp37 = tmp29 + tmp36
         tmp38 = state%cx_s3*tmp37
         call gemv(state%s13, real(state%cx_s19, wp), tmp40, trans="t")
         call gemv(state%s13, aimag(state%cx_s19), tmp41, trans="t")
         tmp39 = cmplx(tmp40, tmp41, wp)
         tmp42 = state%a*tmp39
         tmp43 = 0.15915494309189535_wp*tmp42
         tmp44 = state%cx_s19 + tmp43
         call gemv(state%cx_s12, real(tmp44, wp), tmp46)
         call gemv(state%cx_s12, aimag(tmp44), tmp47)
         tmp45 = cmplx(tmp46, tmp47, wp)
         tmp48 = state%cx_s2*tmp45
         tmp49 = tmp38 + tmp48
         tmp50 = -tmp49
         tmp51 = tmp14 + tmp50
         tmp52 = sum(tmp28*tmp51)
         call gemv(state%s7, real(state%cx_s17, wp), tmp54)
         call gemv(state%s7, aimag(state%cx_s17), tmp55)
         tmp53 = cmplx(tmp54, tmp55, wp)
         tmp56 = -tmp53
         tmp57 = tmp9 + tmp56
         tmp58 = sum(state%cx_s23*tmp57)
         tmp59 = tmp52 + tmp58
         energy = energy + tmp59
      end if

      state%cx_ready = 3
   end subroutine lpb_point_complex_solve

   !> Linearized Poisson-Boltzmann (point charges): energy gradient with respect to the other inputs
   !>
   !> - For the inputs of the last solve
   !> - Needs lpb_point_complex_solve on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of lpb_point
   !> @param[out] grad_r  partial derivative of the energy with respect to r
   !> @param[out] grad_n  partial derivative of the energy with respect to n
   !> @param[out] grad_k1  partial derivative of the energy with respect to k1
   !> @param[out] grad_k2  partial derivative of the energy with respect to k2
   !> @param[out] grad_a  partial derivative of the energy with respect to a
   !> @param[out] grad_eps  partial derivative of the energy with respect to eps
   !> @param[out] grad_kappa  partial derivative of the energy with respect to kappa
   !> @param[out] error  error handling; allocated on failure
   subroutine lpb_point_complex_weights(state, grad_r, grad_n, grad_k1, grad_k2, grad_a, grad_eps, &
                                        grad_kappa, error)
      !> State of lpb_point
      type(lpb_point_complex_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to r
      complex(wp), contiguous, intent(out) :: grad_r(:, :)
      !> Partial derivative of the energy with respect to n
      complex(wp), contiguous, intent(out) :: grad_n(:, :)
      !> Partial derivative of the energy with respect to k1
      complex(wp), contiguous, intent(out) :: grad_k1(:)
      !> Partial derivative of the energy with respect to k2
      complex(wp), contiguous, intent(out) :: grad_k2(:)
      !> Partial derivative of the energy with respect to a
      complex(wp), contiguous, intent(out) :: grad_a(:)
      !> Partial derivative of the energy with respect to eps
      complex(wp), intent(out) :: grad_eps
      !> Partial derivative of the energy with respect to kappa
      complex(wp), intent(out) :: grad_kappa
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:), tmp5(:), tmp6(:), tmp250(:), &
                               tmp251(:), tmp257(:), tmp258(:)
      real(wp) :: tmp9, tmp10, tmp11, tmp12, tmp13, tmp14, tmp15, tmp16, tmp17, tmp18, tmp19, &
                  tmp20, tmp25, tmp26, tmp27, tmp28, tmp29, tmp30
      complex(wp), allocatable :: tmp7(:), tmp8(:), tmp21(:), tmp22(:), tmp23(:), tmp24(:), &
                                  tmp31(:), tmp32(:), tmp33(:), tmp34(:), tmp35(:), tmp36(:), &
                                  tmp37(:), tmp38(:), tmp39(:), tmp40(:), tmp41(:), tmp42(:), &
                                  tmp43(:), tmp44(:), tmp45(:), tmp46(:), tmp47(:), tmp230(:), &
