   !> Linearized Poisson-Boltzmann (point charges): linear response of the v gradient
   !>
   !> - Directions of v only; the state is not changed
   !> - Needs lpb_point_complex_solve on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of lpb_point
   !> @param[in] dv  direction for v
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine lpb_point_complex_response(state, dv, hvp_v, error)
      !> State of lpb_point
      type(lpb_point_complex_state), intent(inout) :: state
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:, :)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call lpb_point_complex_mf_response(state, dv, hvp_v, error)
         return
      end if
      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, "[lpb_point_complex_response] call lpb_point_complex_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[lpb_point_complex_response] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[lpb_point_complex_response] hvp_v: wrong shape")
         return
      end if
      do blk = 1, nblk
         call lpb_point_complex_response_one(state, dv(:, blk), hvp_v(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine lpb_point_complex_response

   !> One direction of lpb_point_complex_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of lpb_point
   !> @param[in] dv  direction for v
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine lpb_point_complex_response_one(state, dv, hvp_v, error)
      !> State of lpb_point
      type(lpb_point_complex_state), target, intent(inout) :: state
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp3(:), tmp4(:), tmp9(:), tmp10(:), tmp15(:), tmp16(:), tmp24(:), &
                               tmp25(:), tmp32(:), tmp33(:), tmp36(:), tmp37(:)
      complex(wp), allocatable :: tmp1(:), tmp2(:), tmp5(:), tmp6(:), tmp7(:), tmp8(:), tmp11(:), &
                                  tmp12(:), tmp13(:), tmp14(:), tmp17(:), tmp18(:), tmp19(:), &
                                  tmp20(:), tmp21(:), tmp22(:), tmp23(:), tmp26(:), tmp27(:), &
                                  tmp28(:), tmp29(:), tmp30(:), tmp31(:), tmp34(:), tmp35(:), &
                                  tmp38(:), tmp39(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[lpb_point_complex_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[lpb_point_complex_response_one] hvp_v: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp8(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat == 0) allocate (tmp11(npt), stat=stat)
      if (stat == 0) allocate (tmp12(npt), stat=stat)
      if (stat == 0) allocate (tmp13(npt), stat=stat)
      if (stat == 0) allocate (tmp14(npt), stat=stat)
      if (stat == 0) allocate (tmp15(npt), stat=stat)
      if (stat == 0) allocate (tmp16(npt), stat=stat)
      if (stat == 0) allocate (tmp17(npt), stat=stat)
      if (stat == 0) allocate (tmp18(npt), stat=stat)
      if (stat == 0) allocate (tmp19(npt), stat=stat)
      if (stat == 0) allocate (tmp20(npt), stat=stat)
      if (stat == 0) allocate (tmp21(npt), stat=stat)
      if (stat == 0) allocate (tmp22(npt), stat=stat)
      if (stat == 0) allocate (tmp23(npt), stat=stat)
      if (stat == 0) allocate (tmp24(npt), stat=stat)
      if (stat == 0) allocate (tmp25(npt), stat=stat)
      if (stat == 0) allocate (tmp26(npt), stat=stat)
      if (stat == 0) allocate (tmp27(npt), stat=stat)
      if (stat == 0) allocate (tmp28(npt), stat=stat)
      if (stat == 0) allocate (tmp29(npt), stat=stat)
      if (stat == 0) allocate (tmp30(npt), stat=stat)
      if (stat == 0) allocate (tmp31(npt), stat=stat)
      if (stat == 0) allocate (tmp32(npt), stat=stat)
      if (stat == 0) allocate (tmp33(npt), stat=stat)
      if (stat == 0) allocate (tmp34(npt), stat=stat)
      if (stat == 0) allocate (tmp35(npt), stat=stat)
      if (stat == 0) allocate (tmp36(npt), stat=stat)
      if (stat == 0) allocate (tmp37(npt), stat=stat)
      if (stat == 0) allocate (tmp38(npt), stat=stat)
      if (stat == 0) allocate (tmp39(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[lpb_point_complex_response_one] allocation failed")
         return
      end if

      state%op1%points => state%r
      state%op1%c1 => state%s7
      state%op5%points => state%r
      state%op5%a => state%a
      state%op5%c2 => state%s7
      state%op5%c3 => state%cx_s11
      state%op5%c5 => state%cx_s12
      state%op5%c6 => state%s13
      tmp1 = state%a*dv
      call gemv(state%cx_s11, real(tmp1, wp), tmp3)
      call gemv(state%cx_s11, aimag(tmp1), tmp4)
      tmp2 = cmplx(tmp3, tmp4, wp)
      tmp5 = (-0.15915494309189535_wp)*tmp2
      tmp6 = dv + tmp5
      tmp7 = state%cx_s14*tmp6
      call gemv(state%s13, real(tmp1, wp), tmp9)
      call gemv(state%s13, aimag(tmp1), tmp10)
      tmp8 = cmplx(tmp9, tmp10, wp)
      tmp11 = (-0.15915494309189535_wp)*tmp8
      tmp12 = dv + tmp11
      tmp13 = 0.0_wp
      call state%solver%solve_complex(state%op1, .false., tmp12, tmp13, error)
      if (allocated(error)) return
      call gemv(state%cx_s12, real(tmp13, wp), tmp15)
      call gemv(state%cx_s12, aimag(tmp13), tmp16)
      tmp14 = cmplx(tmp15, tmp16, wp)
      tmp17 = state%cx_s2*tmp14
      tmp18 = tmp7 + tmp17
      tmp19 = 0.0_wp
      call state%solver%solve_complex(state%op5, .false., tmp18, tmp19, error)
      if (allocated(error)) return
      tmp20 = 0.5_wp*tmp19
      tmp21 = 0.0_wp
      call state%solver%solve_complex(state%op5, .true., dv, tmp21, error)
      if (allocated(error)) return
      tmp22 = state%cx_s20*tmp21
      call gemv(state%cx_s12, real(tmp22, wp), tmp24, trans="t")
      call gemv(state%cx_s12, aimag(tmp22), tmp25, trans="t")
      tmp23 = cmplx(tmp24, tmp25, wp)
      tmp26 = 0.0_wp
      call state%solver%solve_complex(state%op1, .false., tmp23, tmp26, error)
      if (allocated(error)) return
      tmp27 = tmp20 + tmp26
      tmp28 = state%cx_s24*tmp21
      tmp29 = tmp27 + tmp28
      tmp30 = (-0.15915494309189535_wp)*tmp26
      call gemv(state%s13, real(tmp30, wp), tmp32, trans="t")
      call gemv(state%s13, aimag(tmp30), tmp33, trans="t")
      tmp31 = cmplx(tmp32, tmp33, wp)
      tmp34 = state%cx_s27*tmp21
      call gemv(state%cx_s11, real(tmp34, wp), tmp36, trans="t")
      call gemv(state%cx_s11, aimag(tmp34), tmp37, trans="t")
      tmp35 = cmplx(tmp36, tmp37, wp)
      tmp38 = tmp31 + tmp35
      tmp39 = tmp38*state%a
      hvp_v = tmp29 + tmp39
   end subroutine lpb_point_complex_response_one

   !> Linearized Poisson-Boltzmann (point charges): build the cavity operators
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of lpb_point
   !> @param[in] r  positions of the surface points
   !> @param[in] n  outward unit normals at the surface points
   !> @param[in] k1  first principal curvature (positive where convex)
   !> @param[in] k2  second principal curvature (positive where convex)
   !> @param[in] a  tessera areas, switched (ISWIG: F_i R_I^2 w_i)
   !> @param[out] error  error handling; allocated on failure
   !> @param[in] solver  linear solver, copied into the state; default dense LAPACK (Cholesky,
   !> symmetric or LU)
   subroutine lpb_point_mf_assemble(state, r, n, k1, k2, a, error, solver)
      !> State of lpb_point
      type(lpb_point_state), target, intent(inout) :: state
      !> Positions of the surface points
      real(wp), contiguous, intent(in) :: r(:, :)
      !> Outward unit normals at the surface points
      real(wp), contiguous, intent(in) :: n(:, :)
      !> First principal curvature (positive where convex)
      real(wp), contiguous, intent(in) :: k1(:)
      !> Second principal curvature (positive where convex)
      real(wp), contiguous, intent(in) :: k2(:)
      !> Tessera areas, switched (ISWIG: F_i R_I^2 w_i)
      real(wp), contiguous, intent(in) :: a(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error
      !> Linear solver
      class(pcm_solver), intent(in), optional :: solver

      integer :: npt
      integer :: stat

      stat = 0
      npt = size(r, 2)
      if (npt < 1) then
         call fatal_error(error, "[lpb_point_mf_assemble] empty discretization")
         return
      end if
      if (any(shape(r) /= [3, npt])) then
         call fatal_error(error, "[lpb_point_mf_assemble] r: wrong shape")
         return
      end if
      if (any(shape(n) /= [3, npt])) then
         call fatal_error(error, "[lpb_point_mf_assemble] n: wrong shape")
         return
      end if
      if (any(shape(k1) /= [npt])) then
         call fatal_error(error, "[lpb_point_mf_assemble] k1: wrong shape")
         return
      end if
      if (any(shape(k2) /= [npt])) then
         call fatal_error(error, "[lpb_point_mf_assemble] k2: wrong shape")
         return
      end if
      if (any(shape(a) /= [npt])) then
         call fatal_error(error, "[lpb_point_mf_assemble] a: wrong shape")
         return
      end if
      state%ready = 0
      if (allocated(state%solver)) deallocate (state%solver)
      if (allocated(state%v)) deallocate (state%v)
      if (allocated(state%r)) deallocate (state%r)
      if (allocated(state%a)) deallocate (state%a)
      if (allocated(state%n)) deallocate (state%n)
      if (allocated(state%k1)) deallocate (state%k1)
      if (allocated(state%k2)) deallocate (state%k2)
      if (allocated(state%s8)) deallocate (state%s8)
      if (allocated(state%s4)) deallocate (state%s4)
      if (allocated(state%s5)) deallocate (state%s5)
      if (allocated(state%s9)) deallocate (state%s9)
      if (allocated(state%s6)) deallocate (state%s6)
      if (allocated(state%s10)) deallocate (state%s10)
      if (allocated(state%s15)) deallocate (state%s15)
      if (allocated(state%s16)) deallocate (state%s16)
      if (allocated(state%s17)) deallocate (state%s17)
      if (allocated(state%s18)) deallocate (state%s18)
      if (allocated(state%s19)) deallocate (state%s19)
      if (allocated(state%s21)) deallocate (state%s21)
      if (allocated(state%s22)) deallocate (state%s22)
      if (allocated(state%s23)) deallocate (state%s23)
      if (allocated(state%s25)) deallocate (state%s25)
      if (allocated(state%s26)) deallocate (state%s26)
      if (allocated(state%s28)) deallocate (state%s28)
      if (allocated(state%s29)) deallocate (state%s29)
      if (allocated(state%s30)) deallocate (state%s30)
      if (allocated(state%s31)) deallocate (state%s31)
      if (allocated(state%s32)) deallocate (state%s32)
      if (allocated(state%s33)) deallocate (state%s33)
      if (allocated(state%s34)) deallocate (state%s34)
      if (allocated(state%s36)) deallocate (state%s36)
      if (allocated(state%s37)) deallocate (state%s37)
      if (allocated(state%s38)) deallocate (state%s38)
      if (allocated(state%s40)) deallocate (state%s40)
      if (allocated(state%s41)) deallocate (state%s41)
      if (allocated(state%s42)) deallocate (state%s42)
      if (allocated(state%s43)) deallocate (state%s43)
      if (allocated(state%s44)) deallocate (state%s44)
      if (allocated(state%s45)) deallocate (state%s45)
      if (allocated(state%s46)) deallocate (state%s46)
      if (allocated(state%s47)) deallocate (state%s47)
      if (allocated(state%s48)) deallocate (state%s48)
      if (allocated(state%s49)) deallocate (state%s49)
      if (allocated(state%s50)) deallocate (state%s50)
      if (allocated(state%s7)) deallocate (state%s7)
      if (allocated(state%s11)) deallocate (state%s11)
      if (allocated(state%s12)) deallocate (state%s12)
      if (allocated(state%s13)) deallocate (state%s13)
      state%npt = npt
      if (present(solver)) then
         allocate (state%solver, source=solver, stat=stat)
      else
         allocate (pcm_dense_solver :: state%solver, stat=stat)
      end if
      if (stat == 0) allocate (state%v(npt), stat=stat)
      if (stat == 0) allocate (state%r(3, npt), stat=stat)
      if (stat == 0) allocate (state%a(npt), stat=stat)
      if (stat == 0) allocate (state%n(3, npt), stat=stat)
      if (stat == 0) allocate (state%k1(npt), stat=stat)
      if (stat == 0) allocate (state%k2(npt), stat=stat)
      if (stat == 0) allocate (state%s8(npt), stat=stat)
      if (stat == 0) allocate (state%s4(npt), stat=stat)
      if (stat == 0) allocate (state%s5(npt), stat=stat)
      if (stat == 0) allocate (state%s9(npt), stat=stat)
      if (stat == 0) allocate (state%s6(npt), stat=stat)
      if (stat == 0) allocate (state%s10(npt), stat=stat)
      if (stat == 0) allocate (state%s15(npt), stat=stat)
      if (stat == 0) allocate (state%s16(npt), stat=stat)
      if (stat == 0) allocate (state%s17(npt), stat=stat)
      if (stat == 0) allocate (state%s18(npt), stat=stat)
      if (stat == 0) allocate (state%s19(npt), stat=stat)
      if (stat == 0) allocate (state%s21(npt), stat=stat)
      if (stat == 0) allocate (state%s22(npt), stat=stat)
      if (stat == 0) allocate (state%s23(npt), stat=stat)
      if (stat == 0) allocate (state%s25(npt), stat=stat)
      if (stat == 0) allocate (state%s26(npt), stat=stat)
      if (stat == 0) allocate (state%s28(npt), stat=stat)
      if (stat == 0) allocate (state%s29(npt), stat=stat)
      if (stat == 0) allocate (state%s30(npt), stat=stat)
      if (stat == 0) allocate (state%s31(npt), stat=stat)
      if (stat == 0) allocate (state%s32(npt), stat=stat)
      if (stat == 0) allocate (state%s33(npt), stat=stat)
      if (stat == 0) allocate (state%s34(npt), stat=stat)
      if (stat == 0) allocate (state%s36(npt), stat=stat)
      if (stat == 0) allocate (state%s37(npt), stat=stat)
      if (stat == 0) allocate (state%s38(npt), stat=stat)
      if (stat == 0) allocate (state%s40(npt), stat=stat)
      if (stat == 0) allocate (state%s41(npt), stat=stat)
      if (stat == 0) allocate (state%s42(npt), stat=stat)
      if (stat == 0) allocate (state%s43(npt), stat=stat)
      if (stat == 0) allocate (state%s44(npt), stat=stat)
      if (stat == 0) allocate (state%s45(npt), stat=stat)
      if (stat == 0) allocate (state%s46(npt), stat=stat)
      if (stat == 0) allocate (state%s47(npt), stat=stat)
      if (stat == 0) allocate (state%s48(npt), stat=stat)
      if (stat == 0) allocate (state%s49(npt), stat=stat)
      if (stat == 0) allocate (state%s50(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[lpb_point_mf_assemble] allocation failed")
         return
      end if
      state%s17 = 0.0_wp
      state%s19 = 0.0_wp
      state%s21 = 0.0_wp
      state%s23 = 0.0_wp
      call state%solver%reset(lpb_point_n_operators)
      state%matrix_free = .true.

      state%r = r
      state%a = a
      state%n = n
      state%k1 = k1
      state%k2 = k2
      state%op3%npt = npt
      state%op3%npoint = npt
      state%op3%id = 3
      state%op3%points => state%r
      state%op3%symmetric = .true.
      state%op3%r => state%r
      state%op3%a => state%a
      call state%solver%setup(state%op3, error)
      if (allocated(error)) return
      state%s8 = state%n(1, :)
      state%s4 = state%r(1, :)
      state%s5 = state%r(2, :)
      state%s9 = state%n(2, :)
      state%s6 = state%r(3, :)
      state%s10 = state%n(3, :)

      state%ready = 1
      state%assembled = state%assembled + 1
   end subroutine lpb_point_mf_assemble

   !> Linearized Poisson-Boltzmann (point charges): combine and factor the operators for the solvent
   !>
   !> - Repeat with new solvent inputs as often as needed; the cavity operators are reused
   !> - Needs lpb_point_assemble on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of lpb_point
   !> @param[in] eps  relative permittivity of the solvent (inf for a conductor)
   !> @param[in] kappa  inverse Debye screening length of the ionic solvent
   !> @param[out] error  error handling; allocated on failure
   subroutine lpb_point_mf_medium(state, eps, kappa, error)
      !> State of lpb_point
      type(lpb_point_state), target, intent(inout) :: state
      !> Relative permittivity of the solvent (inf for a conductor)
      real(wp), intent(in) :: eps
      !> Inverse Debye screening length of the ionic solvent
      real(wp), intent(in) :: kappa
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp) :: tmp1

      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, "[lpb_point_mf_medium] call lpb_point_assemble first")
         return
      end if
      state%ready = 1
      ! Inputs that do not enter these outputs
      associate (unused1 => eps)
      end associate

      state%op3%points => state%r
      state%op3%r => state%r
      state%op3%a => state%a
      state%kappa = kappa
      state%op4%npt = npt
      state%op4%npoint = npt
      state%op4%id = 4
      state%op4%points => state%r
      state%op4%r => state%r
      state%op4%n => state%n
      state%op4%k1 => state%k1
      state%op4%k2 => state%k2
      state%op4%a => state%a
      state%op4%kappa = state%kappa
      state%s1 = eps + 1.0_wp
      state%s2 = 1.0_wp/state%s1
      tmp1 = -state%s2
      state%s3 = 1.0_wp + tmp1
      state%op4%c1 = state%s3
      state%op4%c2 = state%s2
      state%s51 = -state%kappa
      state%op4%c3 = state%s51
      call state%solver%setup(state%op4, error)
      if (allocated(error)) return
      state%s14 = -state%s3
      state%s20 = 0.5_wp*state%s2
      state%s24 = (-0.5_wp)*state%s3
      state%s27 = 0.07957747154594767_wp*state%s3

      state%ready = 2
   end subroutine lpb_point_mf_medium

   !> Linearized Poisson-Boltzmann (point charges): energy, solution and gradient for v
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs lpb_point_medium on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of lpb_point
   !> @param[in] v  solute electrostatic potential at the surface points
   !> @param[out] energy  solvation energy
   !> @param[out] q  apparent surface charges
   !> @param[out] grad_v  partial derivative of the energy with respect to v
   !> @param[out] error  error handling; allocated on failure
   subroutine lpb_point_mf_solve(state, v, energy, q, grad_v, error)
      !> State of lpb_point
      type(lpb_point_state), target, intent(inout) :: state
      !> Solute electrostatic potential at the surface points
      real(wp), contiguous, intent(in) :: v(:)
      !> Solvation energy
      real(wp), intent(out) :: energy
      !> Apparent surface charges
      real(wp), contiguous, intent(out) :: q(:)
      !> Partial derivative of the energy with respect to v
      real(wp), contiguous, intent(out) :: grad_v(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:), tmp9(:), tmp10(:), tmp11(:), tmp12(:), tmp13(:), &
                               tmp19(:), tmp20(:), tmp21(:), tmp68(:), tmp69(:), tmp70(:), &
                               tmp71(:), tmp72(:), tmp108(:), tmp109(:), tmp110(:), tmp112(:), &
                               tmp113(:), tmp114(:), tmp115(:), tmp116(:), tmp117(:), tmp118(:), &
                               tmp123(:), tmp141(:), tmp142(:), tmp143(:), tmp178(:), tmp179(:), &
                               tmp180(:), tmp181(:), tmp182(:), tmp211(:), tmp212(:), tmp213(:), &
                               tmp214(:), tmp215(:), tmp238(:), tmp239(:), tmp240(:), tmp241(:), &
                               tmp243(:), tmp244(:), tmp262(:), tmp263(:)
      real(wp) :: tmp3, tmp4, tmp5, tmp6, tmp7, tmp8, tmp14, tmp15, tmp16, tmp17, tmp18, tmp111, &
                  tmp119, tmp120, tmp121, tmp122, tmp242, tmp264, tmp265
      integer :: i, j

      stat = 0
      npt = state%npt
      if (state%ready < 2) then
         call fatal_error(error, "[lpb_point_mf_solve] call lpb_point_medium first")
         return
      end if
      if (any(shape(v) /= [npt])) then
         call fatal_error(error, "[lpb_point_mf_solve] v: wrong shape")
         return
      end if
      if (any(shape(q) /= [npt])) then
         call fatal_error(error, "[lpb_point_mf_solve] q: wrong shape")
         return
      end if
      if (any(shape(grad_v) /= [npt])) then
         call fatal_error(error, "[lpb_point_mf_solve] grad_v: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat == 0) allocate (tmp11(npt), stat=stat)
      if (stat == 0) allocate (tmp12(npt), stat=stat)
      if (stat == 0) allocate (tmp13(npt), stat=stat)
      if (stat == 0) allocate (tmp19(npt), stat=stat)
