   !> Linearized Poisson-Boltzmann (point charges): linear response of the v gradient
   !>
   !> - Directions of v only; the state is not changed
   !> - Needs lpb_point_solve on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of lpb_point
   !> @param[in] dv  direction for v
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine lpb_point_mf_response(state, dv, hvp_v, error)
      !> State of lpb_point
      type(lpb_point_state), intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:, :)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%ready < 3) then
         call fatal_error(error, "[lpb_point_mf_response] call lpb_point_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[lpb_point_mf_response] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[lpb_point_mf_response] hvp_v: wrong shape")
         return
      end if
      do blk = 1, nblk
         call lpb_point_mf_response_one(state, dv(:, blk), hvp_v(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine lpb_point_mf_response

   !> One direction of lpb_point_mf_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
