   !> Apply operator 5 or its transpose (not conjugated)
   !>
   !> @param[in]  self   operator
   !> @param[in]  trans  apply the transpose if true
   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine lpb_point_op5_apply(self, trans, x, y)
      !> Operator
      class(lpb_point_op5), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
      complex(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      complex(wp), contiguous, intent(out) :: y(:)

      if (trans) then
         block
            real(wp) :: tmp2(self%npt), tmp3(self%npt), tmp8(self%npt), tmp9(self%npt), &
                        tmp12(self%npt), tmp13(self%npt), tmp16(self%npt), tmp17(self%npt)
            complex(wp) :: tmp1(self%npt), tmp4(self%npt), tmp5(self%npt), tmp6(self%npt), &
                           tmp7(self%npt), tmp10(self%npt), tmp11(self%npt), tmp14(self%npt), &
                           tmp15(self%npt), tmp18(self%npt), tmp19(self%npt), tmp20(self%npt)

            call gemv(self%c3, real(x, wp), tmp2, trans="t")
            call gemv(self%c3, aimag(x), tmp3, trans="t")
            tmp1 = cmplx(tmp2, tmp3, wp)
            tmp4 = self%a*tmp1
            tmp5 = (-0.15915494309189535_wp)*tmp4
            tmp6 = x + tmp5
            call gemv(self%c2, real(tmp6, wp), tmp8, trans="t")
            call gemv(self%c2, aimag(tmp6), tmp9, trans="t")
            tmp7 = cmplx(tmp8, tmp9, wp)
            tmp10 = self%c1*tmp7
            call gemv(self%c5, real(x, wp), tmp12, trans="t")
            call gemv(self%c5, aimag(x), tmp13, trans="t")
            tmp11 = cmplx(tmp12, tmp13, wp)
            tmp14 = self%a*tmp11
            call gemv(self%c6, real(tmp14, wp), tmp16)
            call gemv(self%c6, aimag(tmp14), tmp17)
            tmp15 = cmplx(tmp16, tmp17, wp)
            tmp18 = 0.15915494309189535_wp*tmp15
            tmp19 = tmp11 + tmp18
            tmp20 = self%c4*tmp19
            y = tmp10 + tmp20
         end block
      else
         block
            real(wp) :: tmp2(self%npt), tmp3(self%npt), tmp6(self%npt), tmp7(self%npt), &
                        tmp12(self%npt), tmp13(self%npt), tmp18(self%npt), tmp19(self%npt)
            complex(wp) :: tmp1(self%npt), tmp4(self%npt), tmp5(self%npt), tmp8(self%npt), &
                           tmp9(self%npt), tmp10(self%npt), tmp11(self%npt), tmp14(self%npt), &
