            tmp1 = cmplx(tmp2, tmp3, wp)
            tmp4 = self%a*tmp1
            call gemv(self%c3, real(tmp4, wp), tmp6)
            call gemv(self%c3, aimag(tmp4), tmp7)
            tmp5 = cmplx(tmp6, tmp7, wp)
            tmp8 = (-0.15915494309189535_wp)*tmp5
            tmp9 = tmp1 + tmp8
            tmp10 = self%c1*tmp9
            call gemv(self%c6, real(x, wp), tmp12, trans="t")
